template<>struct Wire<FF_RULE> {static Json Encode(const FF_RULE& v){Json j=Json::object();j["Id"]=EncodeWire(v.Id);j["ProcessId"]=EncodeWire(v.ProcessId);j["Operations"]=EncodeWire(v.Operations);j["Action"]=EncodeWire(v.Action);j["PathLength"]=EncodeWire(v.PathLength);j["Reserved"]=EncodeWire(v.Reserved);j["Folder"]=EncodeWire(v.Folder);return j;}static void Decode(const Json& j,FF_RULE& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="Id")DecodeWire(it.value(),v.Id);else if(it.key()=="ProcessId")DecodeWire(it.value(),v.ProcessId);else if(it.key()=="Operations")DecodeWire(it.value(),v.Operations);else if(it.key()=="Action")DecodeWire(it.value(),v.Action);else if(it.key()=="PathLength")DecodeWire(it.value(),v.PathLength);else if(it.key()=="Reserved")DecodeWire(it.value(),v.Reserved);else if(it.key()=="Folder")DecodeWire(it.value(),v.Folder);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
